SELECT u.user_id, u.user_nickname, u.user_personal_signature, f.create_time AS follow_time, f.follow_id FROM ch_follow f JOIN ch_user u ON u.user_id = f.follow_receive_user_id AND u.user_is_delete = 0 WHERE f.follow_sent_user_id = #{userId}
AND (f.create_time < #{cursorTime} OR (f.create_time = #{cursorTime} AND f.follow_id < #{cursorId}))
ORDER BY f.create_time DESC, f.follow_id DESC LIMIT #{pageSize}

